#include<bits/stdc++.h>

using namespace std;
using ll=long long;

ll mod;

ll power(ll a,ll b){ // a^b
  ll res=1,cur=a;
  while(b>0){
    if(b&1ll){
      res*=cur; res%=mod;
    }
    cur*=cur; cur%=mod;
    b>>=1;
  }
  return res;
}

int main(){
  ll k,m;
  cin >> k >> m;
  mod=(m*10007);
  vector<ll> c(k),l(k);
  for(ll i=0;i<k;i++){
    cin >> c[i] >> l[i];
  }

  vector<ll> pow_keep(30); // 10^{2^d}
  pow_keep[0]=10;
  for(ll d=1;d<30;d++){
    pow_keep[d]=(pow_keep[d-1]*pow_keep[d-1])%mod;
  }

  vector<ll> Rpow2(30);
  Rpow2[0]=1;
  for(ll d=1;d<30;d++){
    Rpow2[d]=(Rpow2[d-1]*pow_keep[d-1]+Rpow2[d-1])%mod;
  }

  ll res=0;
  ll dgt=0;
  for(ll i=k-1;i>=0;i--){
    ll ce=(c[i]*power(10,dgt))%mod;
    ll R=0;
    for(ll d=29;d>=0;d--){
      if(l[i]&(1ll<<d)){
        R=(R*pow_keep[d]+Rpow2[d])%mod;
      }
    }
    res+=ce*R; res%=mod;
    dgt+=l[i];
  }
  cout << res/m << "\n";
  return 0;
}

k, m = map(int, input().split())
mod = 10007 * m

def f(n, x):
    if n == 0:
        return 0
    if n % 2:
        return (1 + x * f(n - 1, x)) % mod
    return (1 + x) * f(n // 2, x * x % mod) % mod

ans = 0
for i in range(k):
    c, l = map(int, input().split())
    ans = (pow(10, l, mod) * ans + c * f(l, 10)) % mod
print(ans // m)
